import { stripAnsi } from '../../utils/ansi'

/** Matches the public hostname generated by a Cloudflare Quick Tunnel. */
export const QUICK_TUNNEL_URL_PATTERN =
  /https:\/\/[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.trycloudflare\.com/gi

export function extractQuickTunnelUrl(text: string): string | null {
  const matches = stripAnsi(text).match(QUICK_TUNNEL_URL_PATTERN)
  if (!matches || matches.length === 0) return null
  return matches[0]?.toLowerCase() ?? null
}

/**
 * Stateful detector for streamed cloudflared output. Keeps a tail buffer so a
 * URL split across two stdout chunks is still detected, and only reports each
 * URL once.
 */
export class TunnelUrlDetector {
  private buffer = ''
  private found: string | null = null

  push(chunk: string): string | null {
    this.buffer = (this.buffer + stripAnsi(chunk)).slice(-16_384)
    const url = extractQuickTunnelUrl(this.buffer)
    if (url && url !== this.found) {
      this.found = url
      return url
    }
    return null
  }

  get detectedUrl(): string | null {
    return this.found
  }
}

export function isNamedTunnelConnected(line: string): boolean {
  return /Registered tunnel connection|Connection\s+[0-9a-f-]{8,}\s+registered/i.test(line)
}

export function parseCloudflaredVersion(output: string): string | null {
  const match = output.match(/cloudflared\s+version\s+v?([0-9][0-9A-Za-z.\-+]*)/i)
  return match?.[1] ?? null
}

export function isNewerVersion(latest: string, current: string): boolean {
  const toParts = (value: string): number[] =>
    value
      .replace(/^v/i, '')
      .split(/[^0-9]+/)
      .filter((part) => part.length > 0)
      .map((part) => Number(part))
  const latestParts = toParts(latest)
  const currentParts = toParts(current)
  const length = Math.max(latestParts.length, currentParts.length)
  for (let index = 0; index < length; index += 1) {
    const left = latestParts[index] ?? 0
    const right = currentParts[index] ?? 0
    if (left > right) return true
    if (left < right) return false
  }
  return false
}
